update "ContentValue" set "Value" = '<p>Sharing stories with children helps them to:</p><ul><li>Build language skills</li><li>Learn life lessons</li><li>Understand feelings</li><li>Learn about history and traditional beliefs</li><li>Learn about faraway places</li><li>and things</li><li>Build listening and concentration skills</li><li>Build reading and maths skills</li><li>Use their imaginations</li><li>Learn to love books</li></ul>' where "Value" like '%Build language skills%';
